import bodyParser from 'body-parser';
import { Express } from 'express';
import { getDatabase } from '../utils/getDatabase';
import { saveDatabase } from '../utils/saveDatabase';

export const setupServer = (app: Express) => {
  app.use(bodyParser.json());

  app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', '*');
    res.header('Access-Control-Allow-Headers', '*');
    next();
  });

  app.get('/api/getDatabase', async (req, res) => {
    const [, database] = await getDatabase();

    res.status(200);
    res.json(database);
  });

  app.get('/api/ping', async (req, res) => {
    res.json({}).status(200);
  });

  app.post('/api/saveToDatabase', async (req, res) => {
    try {
      await saveDatabase(req.body);
      res.status(200);
      res.json({
        success: true,
      });
    } catch (e) {
      console.log(e);
      res.status(500);
      res.json({
        success: false,
      });
    }
  });
};

import { useLocation } from 'react-router-dom';

export const useSearchParams = <P extends {}>(): P | null => {
  const { search } = useLocation();
  return getSearchParams(search);
};

export const getSearchParams = <P extends {}>(search: string): P | null => {
  try {
    let obj: any = {};
    const queryParams = new URLSearchParams(search);
    Array.from(queryParams.keys()).forEach((key) => {
      obj[key] = queryParams.get(key);
    });
    return obj;
  } catch (e) {
    console.log('Something went wrong in getSearchParams', e);
    return null;
  }
};

